import math

def evaluate_formula(formula: str, x: float) -> float:
    # Define the functions
    def sqrt(x):
        return math.sqrt(x)

    def abs(x):
        return abs(x)

    def sin(x):
        return math.sin(math.radians(x))

    def cos(x):
        return math.cos(math.radians(x))

