            return x ** 2
        elif formula == 'sqrt(x)':
            return sqrt(x)
        elif formula == 'abs(x)':
            return abs(x)
        elif formula == 'sin(x)':
            return sin(x)
        elif formula == 'cos(x)':
            return cos(x)
        else:
            raise ValueError("Invalid formula")
    except ZeroDivisionError:
        raise ValueError("Cannot divide by zero")

# Example usage
