def selection_sort(arr: list[int]) -> list[int]:
    n = len(arr)
    for i in range(n):
        # Encontrar el índice del menor elemento en el subarray arr[i:n]
        min_idx = i
        for j in range(i+1, n):
            if arr[j] < arr[min_idx]:
                min_idx = j
        # Intercambiar el elemento actual con el menor elemento encontrado
        arr[i], arr[min_idx] = arr[min_idx], arr[i]
    return arr
```

