def boustrophedon_order(matrix: list[list[int]]) -> list[int]:
    if not matrix:
        return []

    result = []
    row_index = 0
    col_index = 0
    direction = 1

    while True:
        result.append(matrix[row_index][col_index])

        # Move to the next position based on the current direction
        if direction == 1:
            if col_index + 1 < len(matrix[0]):
                col_index += 1
            else:
                row_index += 1
                direction = -1
        elif direction == -1:
            if col_index - 1 >= 0:
                col_index -= 1
            else:
                row_index += 1
                direction = 1

        # Check if we've reached the end of the matrix
        if row_index >= len(matrix) or col_index >= len(matrix[0]):
            break

    return result
