def matrix_power_mod(matrix: list[list[int]], exp: int, mod: int) -> list[list[int]]:
    def multiply_matrices(a: list[list[int]], b: list[list[int]]) -> list[list[int]]:
        result = [[0] * len(b[0]) for _ in range(len(a))]
        for i in range(len(a)):
            for j in range(len(b[0])):
                for k in range(len(b)):
                    result[i][j] += a[i][k] * b[k][j]
        return [row % mod for row in result]

    def power_matrix(matrix: list[list[int]], exponent: int) -> list[list[int]]:
        if exponent == 0:
            return [[1] * len(matrix)]  # Identity matrix
        elif exponent % 2 == 0:
            half_power = power_matrix(matrix, exponent // 2)
            return multiply_matrices(half_power, half_power)
        else:
            return multiply_matrices(matrix, power_matrix(matrix, exponent - 1))

    return power_matrix(matrix, exp) % mod
