def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    # Extract all unique moduli
    mods = set()
    for r, m in congruences:
        mods.add(m)

    # Calculate the product of all moduli
    L = 1
    for m in mods:
        L *= m

    # Solve each congruence
    solutions = []
    for r, m in congruences:
        # Find the modular inverse of m modulo L
        inv_m = pow(m, -1, L)

        # Solve the equation x * m ≡ r (mod L)
        x = (r * inv_m) % L

        solutions.append((x, L))

    # Check if there is a solution that satisfies all congruences
    for i in range(len(solutions)):
        for j in range(i+1, len(solutions)):
            if solutions[i][0] != solutions[j][0]:
                return None

    return solutions[0]
