from typing import List, Tuple

def lex_topological_order(n: int, pairs: List[Tuple[int, int]]) -> List[int]:
    if n == 0:
        return []

    # Build adjacency list representation of graph
    adj_list = [[] for _ in range(n)]
    indegree = [0] * n

    for a, b in pairs:
        adj_list[a].append(b)
        indegree[b] += 1

    # Topological sort using Kahn's algorithm
    queue = []
    for i in range(n):
        if indegree[i] == 0:
            queue.append(i)

    sorted_tasks = []
    while queue:
        current_task = queue.pop(0)
        sorted_tasks.append(current_task)

        for neighbor in adj_list[current_task]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                queue.append(neighbor)

    # Check for cycles
    if len(sorted_tasks) != n:
        return []

    return sorted_tasks
