def weighted_edit_cost(source: str, target: str, insert_cost: int, delete_cost: int, replace_cost: int) -> int:
    if source == target:
        return 0

    m = len(source)
    n = len(target)

    # Create a table to store results of subproblems
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the table
    for i in range(1, m + 1):
        dp[i][0] = i * insert_cost

    for j in range(1, n + 1):
        dp[0][j] = j * delete_cost

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if source[i - 1] == target[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = min(dp[i - 1][j] + insert_cost,
                                 dp[i][j - 1] + delete_cost,
                                 dp[i - 1][j - 1] + replace_cost)

    return dp[m][n]
