from datetime import datetime, timedelta

def add_business_days(start: str, n: int, holidays: list[str]) -> str:
    start_date = datetime.strptime(start, "%Y-%m-%d")
    if n == 0:
        return start

    # Adjust for negative days by moving backwards
    if n < 0:
        while n < 0:
            start_date -= timedelta(days=1)
            if start_date.strftime("%A") not in ["Saturday", "Sunday"] and start_date.strftime("%Y-%m-%d") not in holidays:
                n += 1
            elif start_date.strftime("%Y-%m-%d") in holidays:
                n += 7

    # Adjust for positive days by moving forwards
    else:
        while n > 0:
            start_date += timedelta(days=1)
            if start_date.strftime("%A") not in ["Saturday", "Sunday"] and start_date.strftime("%Y-%m-%d") not in holidays:
                n -= 1
            elif start_date.strftime("%Y-%m-%d") in holidays:
                n += 7

    return start_date.strftime("%Y-%m-%d")
