from typing import List, Tuple

def seating_arrangements(guests: List[str], conflicts: List[Tuple[str, str]]) -> List[List[str]]:
    if not guests:
        return [[]]

    # Filter out conflicts that involve guests not in the list
    filtered_conflicts = [(g1, g2) for g1, g2 in conflicts if g1 in guests and g2 in guests]

    def backtrack(current_guests, current_arrangement):
        if len(current_guests) == len(guests):
            arrangements.append(current_arrangement)
            return

        for guest in guests:
            if guest not in current_guests and all(conflict[0] != guest and conflict[1] != guest for conflict in filtered_conflicts):
                backtrack(current_guests + [guest], current_arrangement + [guest])

    arrangements = []
    backtrack([], [])
    return sorted(arrangements)
