from typing import List

def min_slides(grid: List[str]) -> int:
    # Implementación del algoritmo de búsqueda en profundidad (DFS)
    def dfs(x, y):
        if x < 0 or x >= len(grid) or y < 0 or y >= len(grid[0]):
            return False
        if grid[x][y] == '#':
            return False
        if grid[x][y] == 'E':
            return True

        grid[x][y] = '#'  # Marcar la celda como visitada
        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx, ny = x + dx, y + dy
            if dfs(nx, ny):
                return True
        grid[x][y] = '.'  # Restaurar la celda original
        return False

    start_x, start_y = None, None
    end_x, end_y = None, None

    # Encontrar la posición inicial y final
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 'S':
                start_x, start_y = i, j
            elif grid[i][j] == 'E':
                end_x, end_y = i, j

    if start_x is None or start_y is None or end_x is None or end_y is None:
        return -1  # No se encontraron las posiciones iniciales y finales

    # Realizar la búsqueda en profundidad desde la posición inicial
    if not dfs(start_x, start_y):
        return -1  # No se pudo llegar a la posición final

    return 0  # Se llegó a la posición final
