def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    max_lengths = [max(len(cell) for cell in row) for row in rows]
    formatted_rows = []

    for row in rows:
        formatted_row = []
        for i, cell in enumerate(row):
            alignment = aligns[i]
            padding = " " * (max_lengths[i] - len(cell))
            if alignment == "l":
                formatted_row.append(f"{cell}{padding}")
            elif alignment == "r":
                formatted_row.append(f"{padding}{cell}")
            elif alignment == "c":
                formatted_row.append(f"{padding}{cell}{padding}")
            else:
                raise ValueError("Invalid alignment")
        formatted_rows.append("|".join(formatted_row))

    return "\n".join(formatted_rows)
