import re

def is_allowed_webhook(url: str) -> bool:
    # Check if URL starts with https://
    if not url.startswith("https://"):
        return False

    # Remove any trailing slashes or spaces
    url = url.rstrip("/ ")

    # Check for user@ or user:password@
    if "@" in url:
        username, password = url.split("@")
        if len(username) > 0 and len(password) > 0:
            return False

    # Check for port
    if ":" in url:
        _, port = url.split(":")
        if port != "443":
            return False

    # Check for domain name
    domain = url.split("//")[1]
    if "." not in domain:
        return False

    # Split domain into labels
    labels = domain.split(".")

    # Check number of labels
    if len(labels) < 2:
        return False

    # Check each label
    for label in labels:
        if not re.match(r'^[a-zA-Z0-9-]+$', label):
            return False

    # Check last label
    if not re.match(r'^[a-zA-Z]+$', labels[-1]):
        return False

    # Check for localhost or .localhost suffix
    if domain.endswith(('.localhost', '.localhost.')):
        return False

    return True
