from typing import List, Tuple

def process_orders(events: List[Tuple[str, str, int]]) -> Tuple[dict[str, int], List[Tuple[str, int]]]:
    stock = {}
    waiting = []

    for kind, item, quantity in events:
        if kind == 'receive':
            stock[item] = quantity
        elif kind == 'order':
            if item not in stock or stock[item] < quantity:
                waiting.append((item, quantity))
            else:
                stock[item] -= quantity

    return stock, waiting
