def run_bank_ops(balances: dict[str, int], ops: list[tuple]) -> tuple[dict[str, int], list[int]]:
    final_balances = balances.copy()
    failed = []

    for i, op in enumerate(ops):
        operation, account, amount = op

        if account not in balances:
            failed.append(i)
            continue

        if amount <= 0:
            failed.append(i)
            continue

        if operation == 'deposit':
            final_balances[account] += amount
        elif operation == 'withdraw':
            if final_balances[account] >= amount + 2:
                final_balances[account] -= amount + 2
            else:
                failed.append(i)
        elif operation == 'transfer':
            if final_balances[account] < amount + 2 or final_balances[account] - amount < 0:
                failed.append(i)
            else:
                final_balances[account] -= amount + 2
                final_balances[op[1]] += amount
        elif operation == 'freeze':
            if final_balances[account] != 0:
                failed.append(i)
            else:
                final_balances[account] = 0
        elif operation == 'unfreeze':
            if final_balances[account] == 0:
                failed.append(i)
            else:
                final_balances[account] = abs(final_balances[account])

    return final_balances, failed
